select

from spc_region r

    coalesce(r.delete_state, '0') = '0'




                and r.region_id = coalesce(
                    (
                        select max(
                            case
                                when current_region.super_region_id is null or current_region.super_region_id = '' then null
                                else current_region.super_region_id
                            end
                        )
                        from spc_region current_region
                        where current_region.region_id = #{bo.regionId}
                          and coalesce(current_region.delete_state, '0') = '0'
                    ),
                    #{bo.regionId}
                )


                and r.region_id = #{bo.regionId}




        and r.region_id = #{bo.segmId}


        and r.super_region_id = #{bo.parentSegmId}



        and r.region_name like #{segmNameLike}



        and r.region_name like #{standNameLike}


order by r.region_no

